class Solution {
public:
    string encode(string s) {
        int n = s.size();
        vector<vector<string>> dp(n, vector<string>(n, ""));

        for (int len = 1; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                string sub = s.substr(i, len);
                dp[i][j] = sub;
                if (len < 5) continue;

                string doubled = sub + sub;
                size_t pos = doubled.find(sub, 1);
                if (pos < sub.size()) {
                    string period = dp[i][i + (int)pos - 1];
                    string compressed = to_string(sub.size() / pos) + "[" + period + "]";
                    if (compressed.size() < dp[i][j].size()) {
                        dp[i][j] = compressed;
                    }
                }

                for (int k = i; k < j; k++) {
                    if (dp[i][k].size() + dp[k + 1][j].size() < dp[i][j].size()) {
                        dp[i][j] = dp[i][k] + dp[k + 1][j];
                    }
                }
            }
        }
        return dp[0][n - 1];
