class Solution {
    public String encode(String s) {
        int n = s.length();
        String[][] dp = new String[n][n];

        for (int len = 1; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                String sub = s.substring(i, j + 1);
                dp[i][j] = sub;
                if (len < 5) continue;

                String doubled = sub + sub;
                int pos = doubled.indexOf(sub, 1);
                if (pos < sub.length()) {
                    String period = dp[i][i + pos - 1];
                    String compressed = (sub.length() / pos) + "[" + period + "]";
                    if (compressed.length() < dp[i][j].length()) {
                        dp[i][j] = compressed;
                    }
                }

                for (int k = i; k < j; k++) {
                    if (dp[i][k].length() + dp[k + 1][j].length() < dp[i][j].length()) {
                        dp[i][j] = dp[i][k] + dp[k + 1][j];
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
}

var encode = function(s) {
    const n = s.length;
    const dp = Array.from({ length: n }, () => new Array(n).fill(""));

    for (let len = 1; len <= n; len++) {
        for (let i = 0; i <= n - len; i++) {
            const j = i + len - 1;
            const sub = s.slice(i, j + 1);
            dp[i][j] = sub;
            if (len < 5) continue;

            const doubled = sub + sub;
            const pos = doubled.indexOf(sub, 1);
            if (pos < sub.length) {
                const period = dp[i][i + pos - 1];
                const compressed = `${Math.floor(sub.length / pos)}[${period}]`;
                if (compressed.length < dp[i][j].length) {
                    dp[i][j] = compressed;
                }
            }

            for (let k = i; k < j; k++) {
                if (dp[i][k].length + dp[k + 1][j].length < dp[i][j].length) {
                    dp[i][j] = dp[i][k] + dp[k + 1][j];
                }
            }
        }
    }
    return dp[0][n - 1];
};
